SELECT customer_id, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END), 0), 2) AS balance_per_credit, ROUND(AVG(balance), 2) AS avg_balance, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, GROUPING_ID() AS grouping_level FROM accounts GROUP BY ROLLUP (customer_id) ORDER BY balance_per_credit DESC
